{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/credit-packs.json
    Packs of credits as tiles: the amount, a badge, the price and a buy button. Axes: columns (2, 4), item (tile, row), tone, density.
    Props (p): id, title, packs, empty, badges, buy, cols, item, tone, density, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_packs = ($p['packs'] ?? null)}
{var $v_empty = ($p['empty'] ?? '')}
{var $v_badges = ($p['badges'] ?? null)}
{var $v_buy = ($p['buy'] ?? null)}
{var $v_cols = ($p['cols'] ?? '4')}
{var $v_item = ($p['item'] ?? 'tile')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_11}
  {if og_t(og_eq(og_len($v_packs), 0))}
    {=og_include('blocks/empty-state.latte', ['p' => ['icon' => 'coins', 'title' => $v_empty]])|noescape}
  {else}
    {capture $c_10}
      {foreach og_l($v_packs) as $v_pack}
        {capture $c_9}
          {capture $c_8}
            {capture $c_6}
              {if og_t(og_or([og_get($v_pack, ['badge']), og_and([!(og_eq($v_item, 'row')), og_gt(og_count($v_packs, 'badge'), 0)])]))}
                {capture $c_2}
                  {if og_t(og_get($v_pack, ['badge']))}
                    {capture $c_1}
                      {=og_text(og_at($v_badges, og_get($v_pack, ['badge'])))}
                    {/capture}
                    {=og_include('compose/Badge.latte', ['variant' => 'default', 'size' => 'default', 'class' => 'w-fit shrink-0', 'children' => (string) $c_1])|noescape}
                  {/if}
                {/capture}
                {=og_include('compose/Box.latte', ['class' => 'flex min-h-6 items-center', 'attrs' => og_attrs(['data-slot', 'badge-slot']), 'children' => (string) $c_2])|noescape}
              {/if}
              {capture $c_5}
                {capture $c_3}
                  {=og_text(og_get($v_pack, ['name']))}
                {/capture}
                {=og_include('compose/Title.latte', ['as' => 3, 'size' => 'xl', 'weight' => 'bold', 'children' => (string) $c_3])|noescape}
                {capture $c_4}
                  {=og_text(og_money(og_get($v_pack, ['price']), og_get($v_pack, ['currency'])))}
                {/capture}
                {=og_include('compose/Text.latte', ['size' => '2xl', 'weight' => 'bold', 'children' => (string) $c_4])|noescape}
              {/capture}
              {=og_include('compose/Stack.latte', ['gap' => '0', 'class' => 'min-w-0', 'children' => (string) $c_5])|noescape}
            {/capture}
            {=og_include('compose/Stack.latte', ['gap' => '2', 'align' => 'start', 'class' => og_s(og_cnv(['min-w-0', (og_t(og_eq($v_item, 'row')) ? 'flex-1' : '')])), 'children' => (string) $c_6])|noescape}
            {capture $c_7}
              {=og_text($v_buy)}
            {/capture}
            {=og_include('compose/Button.latte', ['variant' => og_s((og_t(og_eq(og_get($v_pack, ['badge']), 'popular')) ? 'default' : 'outline')), 'size' => 'sm', 'type' => 'button', 'class' => og_s(og_cnv(['w-fit shrink-0', (og_t(og_eq($v_item, 'row')) ? '' : 'mt-auto')])), 'children' => (string) $c_7])|noescape}
          {/capture}
          {=og_include('compose/CardContent.latte', ['class' => og_s(og_cnv(['flex h-full gap-4', (og_t(og_eq($v_item, 'row')) ? 'flex-row flex-wrap items-center justify-between' : 'flex-col')])), 'children' => (string) $c_8])|noescape}
        {/capture}
        {=og_include('compose/Card.latte', ['variant' => 'default', 'class' => og_s(og_cnv(['h-full', (og_t(og_eq($v_item, 'row')) ? 'gap-4 p-4' : (og_t(og_eq($v_density, 'compact')) ? 'gap-4 p-4' : ''))])), 'attrs' => og_attrs(['data-badge', og_get($v_pack, ['badge'])]), 'children' => (string) $c_9])|noescape}
      {/foreach}
    {/capture}
    {=og_include('compose/Grid.latte', ['cols' => og_s((og_t(og_eq($v_item, 'row')) ? '1' : og_fit_cols((og_t(og_eq($v_cols, '2')) ? '1-2' : '1-4'), og_len($v_packs)))), 'class' => 'gap-4', 'attrs' => og_attrs(['data-slot', 'items']), 'children' => (string) $c_10])|noescape}
  {/if}
{/capture}
{=og_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'tone' => $v_tone, 'density' => $v_density, 'measure' => (og_t(og_eq($v_item, 'row')) ? '2xl' : 'default'), 'landmarkLabel' => $v_landmarkLabel], 'children' => og_markup($c_11)])|noescape}
